<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
use AISkillsHub\Core\Learning\{Subscriptions,SubscriptionCampaigns,Onboarding};
$service=$core->get('learning_subscriptions');$store=$core->get('account_store');$saved=$service->snapshot();wp_set_current_user($admin);$service->saveConfig(['enabled'=>true,'paused'=>false],$saved['revision']);
$start=function(string$name)use($service,$store,$db,$admin):array{$id=p14_user($name);$password='P14-privacy-'.bin2hex(random_bytes(20));wp_set_current_user($admin);wp_set_password($password,$id);wp_set_current_user($id);$service->request(['locale'=>'en_US','weekly'=>true,'new_resources'=>false,'consent'=>true],bin2hex(random_bytes(32)));$row=$db->row('SELECT * FROM '.$db->table('notification_outbox')." WHERE recipient_user_id=%d AND template_key='newsletter_confirm' ORDER BY id DESC LIMIT 1",[$id]);$token=$store->decryptPayload($row)['token'];p14_assert($service->confirm($token)==='active','Synthetic owner explicitly confirms');return['id'=>$id,'password'=>$password,'email'=>get_userdata($id)->user_email];};
try{
p14_case('protected_metadata_hidden_without_breaking_native_roles_or_blank_key',function()use($start,$service,$db,$admin){$f=$start('guard-native-meta');$id=$f['id'];wp_set_current_user($admin);update_user_meta($id,'nickname','Visible QA nickname');$state=$service->rawState($id);$key=$service->storageKey();$mid=(int)$db->value('SELECT umeta_id FROM '.$db->connection()->usermeta.' WHERE user_id=%d AND meta_key=%s',[$id,$key]);$all=get_user_meta($id);p14_assert(isset($all['nickname'],$all[$db->connection()->prefix.'capabilities'])&&!isset($all[$key]),'Blank-key native read preserves role/nickname but hides consent state');p14_assert(get_user_meta($id,$key,true)===''&&get_user_meta($id,strtoupper($key),true)===''&&false===get_metadata_by_mid('user',$mid),'Exact and case variants cannot expose token context');foreach([$key,strtoupper($key)]as$variant){add_user_meta($id,$variant,'{}');update_user_meta($id,$variant,'{}');delete_user_meta($id,$variant);}update_metadata_by_mid('user',$mid,'{}');delete_metadata_by_mid('user',$mid);p14_assert($service->rawState($id)===$state,'Native add/update/delete/by-mid cannot forge or remove consent');p14_assert(user_can($id,'read')&&!user_can($id,'manage_options'),'Native subscriber role intact after guarded blank-key metadata access');});
p14_case('configuration_guards_do_not_block_domain_save_or_unrelated_native_options',function()use($service,$admin,$run){wp_set_current_user($admin);$before=$service->snapshot();foreach([Subscriptions::OPTION,strtoupper(Subscriptions::OPTION)]as$option){update_option($option,'malformed');p14_reject(fn()=>delete_option($option),'Native delete of reserved marketing config denied');}p14_assert($service->snapshot()===$before,'Reserved config unchanged after native bypass attempts');$name='aish_p14_unrelated_'.$run;p14_assert(add_option($name,'before','','no'),'Ordinary native option creation works');p14_assert(update_option($name,'after')&&get_option($name)==='after'&&delete_option($name),'Ordinary native option update/delete unaffected');$service->saveConfig(['enabled'=>true,'paused'=>true],$before['revision']);p14_assert($service->snapshot()['paused'],'Domain CAS still controls config');$service->saveConfig(['enabled'=>true,'paused'=>false],$service->snapshot()['revision']);});
p14_case('native_email_round_trip_does_not_revive_previous_marketing_consent',function()use($start,$service,$accounts,$store,$db,$admin){$f=$start('guard-round-trip');$id=$f['id'];$original=$f['email'];foreach(['round-trip-'.$id.'@example.invalid',$original]as$email){wp_set_current_user($admin);$changed=wp_update_user(['ID'=>$id,'user_email'=>$email]);p14_assert(!is_wp_error($changed),'Native email change completes');$token=bin2hex(random_bytes(32));$store->transaction(fn()=>$store->issueVerification($id,'verify_email',$email,$token));wp_set_current_user($id);$accounts->verify($token);p14_assert($accounts->verified($id),'New native address verified by original account flow');p14_assert($service->accountPreferences()['state']!=='active','Changed address cannot reuse previous newsletter consent');}p14_assert($service->rawState($id)['state']==='paused'&&$service->rawState($id)['confirmed_at']==='','Returning to original address remains revoked until new explicit opt-in');});
p14_case('account_service_email_change_inside_transaction_has_no_nested_transaction_failure',function()use($start,$service,$accounts,$store,$db){$f=$start('guard-account-email');wp_set_current_user($f['id']);$next='account-email-'.$f['id'].'@example.invalid';$accounts->requestEmailChange($f['password'],$next,'en_US');$row=$db->row('SELECT * FROM '.$db->table('notification_outbox')." WHERE recipient_user_id=%d AND template_key='change_email' ORDER BY id DESC LIMIT 1",[$f['id']]);p14_assert($row!==null,'Native service queues email-change verification');$token=$store->decryptPayload($row)['token'];$accounts->verify($token);p14_assert(get_userdata($f['id'])->user_email===$next&&$accounts->verified($f['id']),'Native account transaction commits new verified email');wp_set_current_user($f['id']);p14_assert($service->accountPreferences()['state']!=='active','Newsletter consent revoked within account email transaction');});
p14_case('confirmed_native_privacy_eraser_clears_help_and_subscription_only_for_owner',function()use($start,$service,$core,$admin,$db){$f=$start('guard-native-erasure');$other=$start('guard-native-erasure-other');$before=$service->rawState($other['id']);wp_set_current_user($f['id']);$core->get('learning_onboarding')->complete('account');$privacy=$core->get('account_privacy');$request=$privacy->request('erase',$f['password']);wp_set_current_user($admin);wp_update_post(['ID'=>$request,'post_status'=>'request-confirmed']);$r=$privacy->eraser($f['email']);p14_assert($r['items_removed']&&$r['done'],'Actual confirmed native account privacy workflow completes');p14_assert($service->rawState($f['id'])===null&&!$db->value('SELECT COUNT(*) FROM '.$db->connection()->usermeta.' WHERE user_id=%d AND meta_key=%s',[$f['id'],Onboarding::META]),'Owned subscription and onboarding data removed');p14_assert($service->rawState($other['id'])===$before&&get_userdata($f['id'])instanceof WP_User,'Other owner preserved and erasure does not secretly delete native identity');});
p14_case('native_user_deletion_and_reserved_metadata_remain_compatible',function()use($start,$service,$admin,$db){$f=$start('guard-native-deletion');wp_set_current_user($admin);p14_assert(wp_delete_user($f['id']),'Original WordPress deletion succeeds with protected subscription metadata');p14_assert(!get_userdata($f['id'])&&$service->rawState($f['id'])===null,'No native identity or consent metadata remains after owned deletion');p14_assert(!(int)$db->value('SELECT COUNT(*) FROM '.$db->table('notification_outbox')." WHERE recipient_user_id=%d AND template_key LIKE 'newsletter_%%' AND status IN ('queued','retry','claimed','sending')",[$f['id']]),'Deleted account has no sendable marketing row');});
}finally{wp_set_current_user($admin);$service->saveConfig(array_intersect_key($saved,['enabled'=>true,'paused'=>true]),$service->snapshot()['revision']);}
p14_report('Real WordPress/MySQL native metadata guards, verified email change round trip, confirmed native privacy erasure and native user deletion; no real SMTP or external API');
